type Task = {
  id: string;
  duration: number;
  dependsOn: string[];
};

type Schedule = {
  order: string[];
  layers: string[][];
  earliest: Record<string, { start: number; finish: number }>;
  totalDuration: number;
  criticalPath: string[];
};

class CliError extends Error {}

function compareSequences(a: string[], b: string[]): number {
  const length = Math.min(a.length, b.length);
  for (let i = 0; i < length; i++) {
    const comparison = a[i].localeCompare(b[i]);
    if (comparison !== 0) return comparison;
  }
  return a.length - b.length;
}

function parseTasks(value: unknown): Task[] {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    throw new CliError("input must be a JSON object");
  }

  const tasksValue = (value as Record<string, unknown>).tasks;
  if (!Array.isArray(tasksValue)) {
    throw new CliError('"tasks" must be an array');
  }

  const tasks: Task[] = [];
  const ids = new Set<string>();

  for (let index = 0; index < tasksValue.length; index++) {
    const raw = tasksValue[index];
    const location = `tasks[${index}]`;
    if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
      throw new CliError(`${location} must be an object`);
    }

    const item = raw as Record<string, unknown>;
    if (typeof item.id !== "string" || item.id.length === 0) {
      throw new CliError(`${location}.id must be a non-empty string`);
    }
    if (ids.has(item.id)) {
      throw new CliError(`duplicate task id: ${JSON.stringify(item.id)}`);
    }
    if (typeof item.duration !== "number" || !Number.isFinite(item.duration) || item.duration < 0) {
      throw new CliError(`${location}.duration must be a finite non-negative number`);
    }

    const dependencies = item.dependsOn === undefined ? [] : item.dependsOn;
    if (!Array.isArray(dependencies)) {
      throw new CliError(`${location}.dependsOn must be an array of strings`);
    }
    const seenDependencies = new Set<string>();
    for (let depIndex = 0; depIndex < dependencies.length; depIndex++) {
      const dependency = dependencies[depIndex];
      if (typeof dependency !== "string") {
        throw new CliError(`${location}.dependsOn[${depIndex}] must be a string`);
      }
      if (seenDependencies.has(dependency)) {
        throw new CliError(`${location}.dependsOn contains duplicate id: ${JSON.stringify(dependency)}`);
      }
      if (dependency === item.id) {
        throw new CliError(`task ${JSON.stringify(item.id)} cannot depend on itself`);
      }
      seenDependencies.add(dependency);
    }

    ids.add(item.id);
    tasks.push({ id: item.id, duration: item.duration, dependsOn: [...dependencies] as string[] });
  }

  for (const task of tasks) {
    for (const dependency of task.dependsOn) {
      if (!ids.has(dependency)) {
        throw new CliError(`task ${JSON.stringify(task.id)} depends on unknown id ${JSON.stringify(dependency)}`);
      }
    }
  }

  return tasks;
}

function findCycle(tasks: Task[]): string[] {
  const dependencies = new Map(tasks.map((task) => [task.id, [...task.dependsOn].sort()]));
  const state = new Map<string, 0 | 1 | 2>();
  const stack: string[] = [];
  const stackIndex = new Map<string, number>();

  function visit(id: string): string[] | undefined {
    state.set(id, 1);
    stackIndex.set(id, stack.length);
    stack.push(id);

    for (const dependency of dependencies.get(id)!) {
      if ((state.get(dependency) ?? 0) === 0) {
        const cycle = visit(dependency);
        if (cycle) return cycle;
      } else if (state.get(dependency) === 1) {
        return [...stack.slice(stackIndex.get(dependency)!), dependency];
      }
    }

    stack.pop();
    stackIndex.delete(id);
    state.set(id, 2);
    return undefined;
  }

  for (const id of [...dependencies.keys()].sort()) {
    if ((state.get(id) ?? 0) === 0) {
      const cycle = visit(id);
      if (cycle) return cycle;
    }
  }
  return [];
}

function insertSorted(values: string[], value: string): void {
  let low = 0;
  let high = values.length;
  while (low < high) {
    const middle = (low + high) >>> 1;
    if (values[middle].localeCompare(value) < 0) low = middle + 1;
    else high = middle;
  }
  values.splice(low, 0, value);
}

function plan(tasks: Task[]): Schedule {
  const byId = new Map(tasks.map((task) => [task.id, task]));
  const dependents = new Map<string, string[]>(tasks.map((task) => [task.id, []]));
  const remaining = new Map<string, number>();
  for (const task of tasks) {
    remaining.set(task.id, task.dependsOn.length);
    for (const dependency of task.dependsOn) dependents.get(dependency)!.push(task.id);
  }
  for (const values of dependents.values()) values.sort();

  const ready = tasks.filter((task) => task.dependsOn.length === 0).map((task) => task.id).sort();
  const order: string[] = [];
  while (ready.length > 0) {
    const id = ready.shift()!;
    order.push(id);
    for (const dependent of dependents.get(id)!) {
      const count = remaining.get(dependent)! - 1;
      remaining.set(dependent, count);
      if (count === 0) insertSorted(ready, dependent);
    }
  }

  if (order.length !== tasks.length) {
    throw new CliError(`dependency cycle: ${findCycle(tasks).join(" -> ")}`);
  }

  const layers: string[][] = [];
  const layerById = new Map<string, number>();
  const earliest: Record<string, { start: number; finish: number }> = {};
  const paths = new Map<string, string[]>();

  for (const id of order) {
    const task = byId.get(id)!;
    let layer = 0;
    let start = 0;
    let bestPrefix: string[] = [];
    for (const dependency of task.dependsOn) {
      layer = Math.max(layer, layerById.get(dependency)! + 1);
      const finish = earliest[dependency].finish;
      const candidate = paths.get(dependency)!;
      if (finish > start || (finish === start && compareSequences(candidate, bestPrefix) < 0)) {
        start = finish;
        bestPrefix = candidate;
      }
    }
    layerById.set(id, layer);
    (layers[layer] ??= []).push(id);
    earliest[id] = { start, finish: start + task.duration };
    paths.set(id, [...bestPrefix, id]);
  }
  for (const layer of layers) layer.sort();

  let totalDuration = 0;
  let criticalPath: string[] = [];
  let hasCriticalPath = false;
  for (const id of order) {
    const finish = earliest[id].finish;
    const candidate = paths.get(id)!;
    if (
      !hasCriticalPath ||
      finish > totalDuration ||
      (finish === totalDuration && compareSequences(candidate, criticalPath) < 0)
    ) {
      totalDuration = finish;
      criticalPath = candidate;
      hasCriticalPath = true;
    }
  }

  return { order, layers, earliest, totalDuration, criticalPath };
}

async function main(args: string[]): Promise<void> {
  if (args.length === 0) throw new CliError("usage: bun run src/cli.ts plan INPUT.json");
  if (args[0] !== "plan") throw new CliError(`unknown command: ${args[0]}`);
  if (args.length < 2) throw new CliError("missing input file\nusage: bun run src/cli.ts plan INPUT.json");
  if (args.length > 2) {
    const extra = args.slice(2).join(" ");
    throw new CliError(`unknown argument${args.length > 3 ? "s" : ""}: ${extra}`);
  }
  if (args[1].startsWith("-")) throw new CliError(`unknown flag: ${args[1]}`);

  let text: string;
  try {
    text = await Bun.file(args[1]).text();
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new CliError(`cannot read ${JSON.stringify(args[1])}: ${message}`);
  }

  let input: unknown;
  try {
    input = JSON.parse(text);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new CliError(`invalid JSON in ${JSON.stringify(args[1])}: ${message}`);
  }

  console.log(JSON.stringify(plan(parseTasks(input))));
}

try {
  await main(Bun.argv.slice(2));
} catch (error) {
  const message = error instanceof Error ? error.message : String(error);
  console.error(`error: ${message}`);
  process.exitCode = 1;
}
